import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rm, stat } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { DeleteObjectCommand, GetObjectCommand, HeadObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

/**
 * Object storage for attachments (`BE-0710`, `BE-0711`, `BE-0011`).
 *
 * Keys are opaque and generated by the service — a user's file name never
 * reaches storage. Production uses private S3 with server-side encryption and
 * a declared SHA-256 the bucket itself verifies; the browser uploads straight
 * to a short-lived presigned URL and downloads through one. The local store
 * exists for development and tests only, confines every key to its root, and
 * streams both directions through the authenticated application.
 */
export interface UploadTarget {
  readonly method: 'PUT';
  readonly url: string;
  /** Headers the client must send unchanged; they are part of the signature. */
  readonly headers: Readonly<Record<string, string>>;
  readonly expiresAt: string;
}

export type DownloadTarget =
  | { readonly kind: 'redirect'; readonly url: string; readonly expiresAt: string }
  | { readonly kind: 'stream'; readonly body: Readable; readonly sizeBytes: number };

export interface ObjectStore {
  /** Whether bytes arrive through the application (`receive`) rather than a presigned URL. */
  readonly receivesThroughApplication: boolean;
  uploadTarget(key: string, file: { readonly attachmentId: string; readonly mediaType: string; readonly sizeBytes: number; readonly sha256: string; readonly expiresSeconds: number }): Promise<UploadTarget>;
  /** Local store only: write at most `maxBytes`, refusing an existing key. */
  write(key: string, body: Readable, maxBytes: number): Promise<number>;
  stat(key: string): Promise<{ readonly sizeBytes: number } | null>;
  read(key: string): Promise<Readable>;
  delete(key: string): Promise<void>;
  downloadTarget(key: string, file: { readonly fileName: string; readonly mediaType: string; readonly expiresSeconds: number }): Promise<DownloadTarget>;
}

/** `attachment; filename*=UTF-8''…` — always a download, never rendered inline. */
export const contentDisposition = (fileName: string) =>
  `attachment; filename="${fileName.replace(/[^\x20-\x7e]|["\\]/g, '_')}"; filename*=UTF-8''${encodeURIComponent(fileName)}`;

const KEY = /^files\/\d{4}\/\d{2}\/[a-f0-9-]{36}$/;
export const assertObjectKey = (key: string) => {
  if (!KEY.test(key)) throw new Error('Refusing an unexpected storage key');
  return key;
};

export class S3ObjectStore implements ObjectStore {
  readonly receivesThroughApplication = false;
  constructor(private readonly client: S3Client, private readonly bucket: string) {
    if (!bucket) throw new Error('A private attachment bucket is required');
  }
  async uploadTarget(key: string, file: { attachmentId: string; mediaType: string; sizeBytes: number; sha256: string; expiresSeconds: number }) {
    const checksum = Buffer.from(file.sha256, 'hex').toString('base64');
    const command = new PutObjectCommand({
      Bucket: this.bucket, Key: assertObjectKey(key), ContentType: file.mediaType, ContentLength: file.sizeBytes,
      ChecksumSHA256: checksum, ServerSideEncryption: 'AES256',
    });
    const url = await getSignedUrl(this.client, command, {
      expiresIn: file.expiresSeconds,
      signableHeaders: new Set(['content-type', 'content-length', 'x-amz-checksum-sha256', 'x-amz-server-side-encryption']),
    });
    return {
      method: 'PUT' as const, url,
      headers: { 'content-type': file.mediaType, 'x-amz-checksum-sha256': checksum, 'x-amz-server-side-encryption': 'AES256' },
      expiresAt: new Date(Date.now() + file.expiresSeconds * 1000).toISOString(),
    };
  }
  async write(): Promise<number> { throw new Error('S3 uploads go to the presigned URL'); }
  async stat(key: string) {
    try {
      const head = await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: assertObjectKey(key) }));
      return { sizeBytes: Number(head.ContentLength ?? 0) };
    } catch (error) {
      if ((error as { name?: string }).name === 'NotFound' || (error as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode === 404) return null;
      throw error;
    }
  }
  async read(key: string) {
    const response = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: assertObjectKey(key) }));
    if (!response.Body) throw new Error('Missing object body');
    return response.Body as Readable;
  }
  async delete(key: string) { await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: assertObjectKey(key) })); }
  async downloadTarget(key: string, file: { fileName: string; mediaType: string; expiresSeconds: number }) {
    const url = await getSignedUrl(this.client, new GetObjectCommand({
      Bucket: this.bucket, Key: assertObjectKey(key),
      ResponseContentDisposition: contentDisposition(file.fileName), ResponseContentType: file.mediaType,
    }), { expiresIn: file.expiresSeconds });
    return { kind: 'redirect' as const, url, expiresAt: new Date(Date.now() + file.expiresSeconds * 1000).toISOString() };
  }
}

export class LocalObjectStore implements ObjectStore {
  readonly receivesThroughApplication = true;
  private readonly root: string;
  constructor(root: string, private readonly baseUrl: string) {
    this.root = resolve(root);
  }
  private path(key: string) {
    const target = resolve(this.root, assertObjectKey(key));
    if (!target.startsWith(this.root + sep)) throw new Error('Refusing a path outside the store');
    return target;
  }
  async uploadTarget(_key: string, file: { attachmentId: string; mediaType: string; expiresSeconds: number }) {
    return {
      method: 'PUT' as const, url: `${this.baseUrl}/api/files?id=${encodeURIComponent(file.attachmentId)}`,
      headers: { 'content-type': file.mediaType }, expiresAt: new Date(Date.now() + file.expiresSeconds * 1000).toISOString(),
    };
  }
  async write(key: string, body: Readable, maxBytes: number) {
    const target = this.path(key);
    await mkdir(dirname(target), { recursive: true });
    let written = 0;
    const limit = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        written += chunk.length;
        callback(written > maxBytes ? new Error('FILE_TOO_LARGE') : null, chunk);
      },
    });
    try {
      // `wx`: a key is written once. A second upload to the same key fails.
      await pipeline(body, limit, createWriteStream(target, { flags: 'wx', mode: 0o600 }));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'EEXIST') await rm(target, { force: true });
      throw error;
    }
    return written;
  }
  async stat(key: string) {
    try { return { sizeBytes: (await stat(this.path(key))).size }; } catch { return null; }
  }
  async read(key: string) { return createReadStream(this.path(key)); }
  async delete(key: string) { await rm(this.path(key), { force: true }); }
  async downloadTarget(key: string) {
    const target = this.path(key);
    return { kind: 'stream' as const, body: createReadStream(target), sizeBytes: (await stat(target)).size };
  }
}

/**
 * The configured store. Production requires S3; the local store is refused
 * there, because nothing would encrypt, replicate or back it up.
 */
export function objectStoreFromEnvironment(environment: NodeJS.ProcessEnv = process.env): ObjectStore {
  const bucket = environment.ATTACHMENT_S3_BUCKET ?? environment.S3_BUCKET;
  if (environment.NODE_ENV === 'production' || (bucket && environment.S3_ACCESS_KEY_ID)) {
    if (!bucket) throw new Error('ATTACHMENT_S3_BUCKET or S3_BUCKET is required in production');
    return new S3ObjectStore(new S3Client({
      region: environment.S3_REGION ?? environment.AWS_REGION ?? 'ap-southeast-1',
      endpoint: environment.S3_ENDPOINT || undefined,
      forcePathStyle: environment.S3_FORCE_PATH_STYLE === 'true',
      ...(environment.S3_ACCESS_KEY_ID && environment.S3_SECRET_ACCESS_KEY
        ? { credentials: { accessKeyId: environment.S3_ACCESS_KEY_ID, secretAccessKey: environment.S3_SECRET_ACCESS_KEY } }
        : {}),
    }), bucket);
  }
  return new LocalObjectStore(environment.LOCAL_OBJECT_STORE_DIR ?? '.data/objects', environment.APP_BASE_URL ?? 'http://localhost:3000');
}
